using namespace std;

int main(){
  long long n,cnt=0;
  cin >> n;
  for(long long a=1;a*a*a<=n;a++){
    for(long long b=a;a*b*b<=n;b++){
      long long uc;
      for(long long c=max(b,(n/(a*b))-5);;c++){
        if(a*b*c<=n){uc=c;}else{break;}
      }
      //cerr << a << ' ' << b << ' ' << uc << '\n';
      cnt+=(uc-b+1);
    }
  }
  cout << cnt << '\n';
  return 0;
}
